var wfMap=null;var WF_QUAL_NAME={0:"Poor",1:"Common",2:"Uncommon",3:"Rare",4:"Epic",5:"Legendary",6:"Artifact",7:"Heirloom"};var WF_CAT_ORDER=["Armor","Weapon","Consumable","Other"];function wfFilters(){return{category:st.wfCat,slot:st.wfSlot,type:st.wfType,quality:st.wfQual,q:st.wfQ};}
